from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/")
async def root(x_header: str = Header(default="default", convert_underscores=True)):
    return {"x_header": x_header}

client = TestClient(app)

def test_underscore_header_accepted_when_convert_underscores_true():
    # This should FAIL (return 422 or not find the header) if the fix is applied.
    # Currently it probably PASSES (returns the value).
    response = client.get("/", headers={"x_header": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_header": "foo"}

def test_hyphen_header_accepted_when_convert_underscores_true():
    response = client.get("/", headers={"x-header": "bar"})
    assert response.status_code == 200
    assert response.json() == {"x_header": "bar"}

def test_underscore_header_accepted_when_convert_underscores_false():
    @app.get("/false")
    async def root_false(x_header: str = Header(default="default", convert_underscores=False)):
        return {"x_header": x_header}

    response = client.get("/false", headers={"x_header": "foo"})
    assert response.status_code == 200
    assert response.json() == {"x_header": "foo"}

if __name__ == "__main__":
    pytest.main([__file__])
